// Prepare batch request body for HubSpot line items
const associations = $input.item.json.results;
return [{ json: {
  properties: ["name","quantity","price","amount","hs_product_id","hs_sku","xero_account","payment_terms","recurringbillingfrequency","hs_total_discount"],
  inputs: associations.map(item => ({ id: item.toObjectId.toString() }))
}}];

// Validate line items and split into invoice buckets
const response = $input.item.json;

// HubSpot batch read wraps results in an outer array
const lineItems = Array.isArray(response)
  ? response[0].results
  : (response.results || []);

const errors = [];
const invoice1Items = [];
const invoice2Items = [];
const recurringMonthlyItems = [];

if (lineItems.length === 0) {
  return [{ json: {
    hasErrors: true,
    errorSummary: "Deal has no line items. Please add products to the deal before closing.",
    errors: []
  }}];
}

lineItems.forEach((item, index) => {
  const props = item.properties;
  const name = props.name || `Line item #${index + 1}`;
  const paymentTerms = props.payment_terms || '';
  const billingFrequency = (props.recurringbillingfrequency || '').toLowerCase();
  const quantity = parseFloat(props.quantity) || 0;
  const sku = props.hs_sku || '';
  const unitPrice = parseFloat(props.price) || 0;
  const discount = parseFloat(props.hs_total_discount) || 0;
  const accountCode = props.xero_account ? String(props.xero_account).padStart(2, '0') : '';
  const itemErrors = [];

  if (!props.name)     itemErrors.push("Missing name");
  if (!paymentTerms)   itemErrors.push("Missing payment terms");
  if (quantity === 0)  itemErrors.push("Quantity is 0");
  if (!sku)            itemErrors.push("Missing SKU - cannot sync with Xero catalog");
  if (unitPrice === 0) itemErrors.push("Price is $0");
  if (!accountCode)    itemErrors.push("Missing Xero account code");

  const validTerms = ['50/50', '100%', 'Recurring'];
  if (paymentTerms && !validTerms.includes(paymentTerms))
    itemErrors.push(`Invalid payment terms: "${paymentTerms}" (must be "50/50", "100%", or "Recurring")`);

  if (paymentTerms === 'Recurring' && !['monthly', 'annually'].includes(billingFrequency))
    itemErrors.push(`Invalid billing frequency: "${props.recurringbillingfrequency}" (must be "Monthly" or "Annually")`);

  if (itemErrors.length > 0) {
    errors.push({ productName: name, issues: itemErrors });
    return;
  }

  const baseItem = {
    ItemCode: sku,
    AccountCode: accountCode,
    Quantity: quantity,
    UnitAmount: unitPrice,
    DiscountAmount: discount > 0 ? discount : 0,
    TaxType: "NONE"
  };

  if (paymentTerms === '50/50') {
    invoice1Items.push({
      ...baseItem,
      Quantity: quantity * 0.5,
      DiscountAmount: discount > 0 ? parseFloat((discount * 0.5).toFixed(2)) : 0,
      Description: name + ' (Payment 1/2)'
    });
    invoice2Items.push({
      ...baseItem,
      Quantity: quantity * 0.5,
      DiscountAmount: discount > 0 ? parseFloat((discount * 0.5).toFixed(2)) : 0,
      Description: name + ' (Payment 2/2)'
    });
  } else if (paymentTerms === '100%') {
    invoice2Items.push({ ...baseItem, Description: name });

  } else if (paymentTerms === 'Recurring' && billingFrequency === 'annually') {
    invoice1Items.push({ ...baseItem, Description: name + ' (Annual)' });

  } else if (paymentTerms === 'Recurring' && billingFrequency === 'monthly') {
    recurringMonthlyItems.push({ ...baseItem, Description: name + ' (Monthly)' });
  }
});

const errorSummary = errors.length > 0
  ? errors.map(e => `Product: ${e.productName}\nIssues: ${e.issues.join(', ')}`).join('\n\n')
  : '';

return [{ json: {
  invoice1Items,
  invoice2Items,
  recurringMonthlyItems,
  hasErrors: errors.length > 0,
  errorSummary,
  errors
}}];

// Prepare Xero invoice payloads from merged line item + contact data
const invoice1Items         = $('Code: Validate line items').first().json.invoice1Items;
const invoice2Items         = $('Code: Validate line items').first().json.invoice2Items;
const recurringMonthlyItems = $('Code: Validate line items').first().json.recurringMonthlyItems;
const contactID             = $('Xero: Get contact').first().json.Contacts[0].ContactID;
const dealName              = $('Hubspot: Get deal').first().json.properties.dealname.value;

const now = new Date();
const addDays = (base, days) => {
  const d = new Date(base);
  d.setDate(d.getDate() + days);
  return d.toISOString().split('T')[0];
};
const addMonths = (base, months) => {
  const d = new Date(base);
  d.setMonth(d.getMonth() + months);
  return d.toISOString().split('T')[0];
};

const has1 = invoice1Items.length > 0;
const has2 = invoice2Items.length > 0;
const invoices = [];

// If only invoice2Items exist (all 100% items), treat as a single invoice with no split suffix
if (!has1 && has2) {
  invoices.push({ json: {
    Type: "ACCREC",
    Contact: { ContactID: contactID },
    LineItems: invoice2Items,
    Date: now.toISOString().split('T')[0],
    DueDate: addDays(now, 7),
    Status: "DRAFT",
    Reference: dealName
  }});
} else {
  // Invoice 1: 50/50 first halves + annual recurring
  if (has1) {
    invoices.push({ json: {
      Type: "ACCREC",
      Contact: { ContactID: contactID },
      LineItems: invoice1Items,
      Date: now.toISOString().split('T')[0],
      DueDate: addDays(now, 7),
      Status: "DRAFT",
      Reference: `${dealName} - Invoice 1`
    }});
  }

  // Invoice 2: 50/50 second halves + 100% items
  if (has2) {
    const date2 = addDays(now, 14);
    invoices.push({ json: {
      Type: "ACCREC",
      Contact: { ContactID: contactID },
      LineItems: invoice2Items,
      Date: date2,
      DueDate: addDays(now, 21),
      Status: "DRAFT",
      Reference: `${dealName} - Invoice 2`
    }});
  }
}

// Monthly recurring: 12 invoices, one per month
if (recurringMonthlyItems.length > 0) {
  for (let i = 0; i < 12; i++) {
    const invoiceDate = addMonths(now, i);
    invoices.push({ json: {
      Type: "ACCREC",
      Contact: { ContactID: contactID },
      LineItems: recurringMonthlyItems,
      Date: invoiceDate,
      DueDate: addDays(new Date(invoiceDate), 7),
      Status: "DRAFT",
      Reference: `${dealName} - Monthly ${i + 1}/12`
    }});
  }
}

return invoices;

// Format Xero invoice details for Slack + Email notification
const invoicesData = $input.all();
const xeroURL = $('Config').first().json.XeroURL;
const baseUrl = `https://go.xero.com/app/${xeroURL}/invoicing/edit/`;

const allInvoices = [];
invoicesData.forEach(item => {
  if (item.json.Invoices && item.json.Invoices.length > 0)
    allInvoices.push(...item.json.Invoices);
});

const contact      = allInvoices[0].Contact;
const contactName  = contact.Name;
const contactEmail = contact.EmailAddress;
const totalAmount  = allInvoices.reduce((sum, inv) => sum + inv.Total, 0);

const formatCurrency = (n) =>
  `${n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

const formatDate = (s) =>
  new Date(s).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

let slackMessage = '';
let emailMessage = '';

// 1 invoice, 1 product
if (allInvoices.length === 1 && allInvoices[0].LineItems.length === 1) {
  const inv = allInvoices[0];
  const li  = inv.LineItems[0];
  const url = `${baseUrl}${inv.InvoiceID}`;

  slackMessage  = `Invoice ${inv.InvoiceNumber} created for ${contactName} (${contactEmail}) for ${formatCurrency(inv.Total)}: ${li.Description}\n\n`;
  slackMessage += `<${url}|Check and approve draft>`;

  emailMessage  = `Invoice ${inv.InvoiceNumber} created for ${contactName} (${contactEmail}) for ${formatCurrency(inv.Total)}: ${li.Description}\n\n`;
  emailMessage += `Check and approve draft: ${url}`;
}
// 1 invoice, 2+ products
else if (allInvoices.length === 1) {
  const inv = allInvoices[0];
  const url = `${baseUrl}${inv.InvoiceID}`;

  slackMessage  = `Invoice ${inv.InvoiceNumber} created for ${contactName} (${contactEmail}) for ${formatCurrency(inv.Total)} as follows:\n`;
  emailMessage  = `Invoice ${inv.InvoiceNumber} created for ${contactName} (${contactEmail}) for ${formatCurrency(inv.Total)} as follows:\n`;

  inv.LineItems.forEach((li, i) => {
    slackMessage += `${i+1}. ${li.Quantity}x ${li.Description}\n`;
    emailMessage += `${i+1}. ${li.Quantity}x ${li.Description}\n`;
  });

  slackMessage += `\n<${url}|Check and approve draft>`;
  emailMessage += `\nCheck and approve draft: ${url}`;
}
// 2+ invoices
else {
  slackMessage  = `Invoices created for ${contactName} (${contactEmail}) for ${formatCurrency(totalAmount)} as follows:\n`;
  emailMessage  = `Invoices created for ${contactName} (${contactEmail}) for ${formatCurrency(totalAmount)} as follows:\n`;

  allInvoices.forEach(inv => {
    const url     = `${baseUrl}${inv.InvoiceID}`;
    const dueDate = formatDate(inv.DueDateString);

    if (inv.LineItems.length === 1) {
      const li       = inv.LineItems[0];
      const discount = li.UnitAmount * li.Quantity - li.LineAmount;
      const discText = discount > 0 ? ` (-${formatCurrency(discount)})` : '';

      slackMessage += `*<${url}|Invoice ${inv.InvoiceNumber}> (due ${dueDate}):*\n`;
      slackMessage += `          ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;

      emailMessage += `Invoice ${inv.InvoiceNumber} (due ${dueDate}):\n`;
      emailMessage += `  ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;
      emailMessage += `  ${url}\n`;
    } else {
      slackMessage += `*<${url}|Invoice ${inv.InvoiceNumber}> (due ${dueDate}) for ${formatCurrency(inv.Total)}:*\n`;
      emailMessage += `Invoice ${inv.InvoiceNumber} (due ${dueDate}) for ${formatCurrency(inv.Total)}:\n`;
      emailMessage += `  ${url}\n`;

      inv.LineItems.forEach(li => {
        const discount = li.UnitAmount * li.Quantity - li.LineAmount;
        const discText = discount > 0 ? ` (-${formatCurrency(discount)})` : '';
        slackMessage += `          ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;
        emailMessage += `  ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;
      });
    }
  });

  if (allInvoices.length === 2) {
    slackMessage += `\nCheck and approve draft of first invoice ${allInvoices[0].InvoiceNumber} on Xero. The second invoice should be approved and sent once the project is completed.`;
    emailMessage += `\nCheck and approve draft of first invoice ${allInvoices[0].InvoiceNumber} on Xero. The second invoice should be approved and sent once the project is completed.`;
  } else {
    slackMessage += `\nCheck and approve draft on Xero by clicking the hyperlinked invoice line above.`;
    emailMessage += `\nCheck and approve draft on Xero using the links above.`;
  }
}

return { json: { slackMessage, emailMessage, contactName, contactEmail, totalAmount, invoiceCount: allInvoices.length }};

