      const discText = discount > 0 ? ` (-${formatCurrency(discount)})` : '';

      slackMessage += `*<${url}|Invoice ${inv.InvoiceNumber}> (due ${dueDate}):*\n`;
      slackMessage += `          ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;

      emailMessage += `Invoice ${inv.InvoiceNumber} (due ${dueDate}):\n`;
      emailMessage += `  ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;
      emailMessage += `  ${url}\n`;
    } else {
      slackMessage += `*<${url}|Invoice ${inv.InvoiceNumber}> (due ${dueDate}) for ${formatCurrency(inv.Total)}:*\n`;
      emailMessage += `Invoice ${inv.InvoiceNumber} (due ${dueDate}) for ${formatCurrency(inv.Total)}:\n`;
      emailMessage += `  ${url}\n`;

      inv.LineItems.forEach(li => {
        const discount = li.UnitAmount * li.Quantity - li.LineAmount;
        const discText = discount > 0 ? ` (-${formatCurrency(discount)})` : '';
        slackMessage += `          ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;
        emailMessage += `  ${li.Quantity}x ${li.Description}${discText} = ${formatCurrency(li.LineAmount)}\n`;
      });
    }
  });

  if (allInvoices.length === 2) {
    slackMessage += `\nCheck and approve draft of first invoice ${allInvoices[0].InvoiceNumber} on Xero. The second invoice should be approved and sent once the project is completed.`;
    emailMessage += `\nCheck and approve draft of first invoice ${allInvoices[0].InvoiceNumber} on Xero. The second invoice should be approved and sent once the project is completed.`;
  } else {
    slackMessage += `\nCheck and approve draft on Xero by clicking the hyperlinked invoice line above.`;
    emailMessage += `\nCheck and approve draft on Xero using the links above.`;
  }
}

return { json: { slackMessage, emailMessage, contactName, contactEmail, totalAmount, invoiceCount: allInvoices.length }};

