const dealstage = $('Hubspot: Get deal').item.json.properties.dealstage.value;
const dealname = $('Hubspot: Get deal').item.json.properties.dealname?.value ?? '';
const framework = $('Hubspot: Get deal').item.json.properties.framework?.value ?? '';
const partner = $json.properties.partner?.value ?? '';
const engagement = $('Hubspot: Get deal').item.json.properties.engagement?.value ?? '';

const isCAP = dealstage === '1297403657';
const isSales = dealstage === '266058586';
const isDrata = partner.includes('Partner1');

if (isDrata && isCAP) {
  const engagementOutput = engagement || 'Accelerator Plan';
  return [{ json: { output: 'CAP', engagement: engagementOutput, dealname, framework } }];
}

if (isDrata && isSales) {
  const engagementOutput = engagement || 'Other Services';
  return [{ json: { output: 'Sales', engagement: engagementOutput, dealname, framework } }];
}

return [{ json: { output: null, engagement: null, dealname, framework } }];

